export const DILATION_FRAGMENT_SHADER = `precision mediump float;
uniform sampler2D uRawMask;
uniform vec2 uTexelSize;
varying vec2 vUv;

void main() {
    vec4 center = texture2D(uRawMask, vUv);
    float active = center.r;
    float disabled = center.a;

    // Edge dilation: sample 5x5 diamond/cross
    float edgeMax = 0.0;
    for (int y = -2; y <= 2; y++) {
        for (int x = -2; x <= 2; x++) {
            if (abs(float(x)) + abs(float(y)) <= 3.0) {
                float v = texture2D(uRawMask, vUv + vec2(float(x), float(y)) * uTexelSize).r;
                edgeMax = max(edgeMax, v);
            }
        }
    }

    // Glow dilation: sample wider radius (radius 6-7)
    float glowMax = 0.0;
    for (int y = -6; y <= 6; y += 2) {
        for (int x = -6; x <= 6; x += 2) {
            float dist = length(vec2(float(x), float(y)));
            if (dist <= 6.5) {
                float v = texture2D(uRawMask, vUv + vec2(float(x), float(y)) * uTexelSize).r;
                glowMax = max(glowMax, v * (1.0 - dist / 7.0));
            }
        }
    }

    float edge = max(0.0, edgeMax - active);
    float glow = max(0.0, glowMax - active * 0.7);

    // uMasks channels:
    // R: Active Compose
    // G: Edge
    // B: Glow
    // A: Disabled Compose
    gl_FragColor = vec4(active, edge, glow, disabled);
}`;
